function formatTimestamp(dateObj){var year=dateObj.getFullYear();var month=(dateObj.getMonth()+1).toString().padStart(2,'0');var day=dateObj.getDate().toString().padStart(2,'0');var hours=dateObj.getHours().toString().padStart(2,'0');var minutes=dateObj.getMinutes().toString().padStart(2,'0');var seconds=dateObj.getSeconds().toString().padStart(2,'0');return year+'-'+month+'-'+day+' '+hours+':'+minutes+':'+seconds;}function calculateExecutionDuration(startTime,endTime){return(endTime-startTime).toFixed(2)+' ms';}function logEvent(message,level){var lvl=level||'INFO';var time=formatTimestamp(new Date());console.log('['+time+']['+lvl+']'+message);}window.Utils={formatTimestamp:formatTimestamp,calculateExecutionDuration:calculateExecutionDuration,logEvent:logEvent};var galleryItems=[{id:1,title:'Edge CDN Network Nodes',category:'Infrastructure',file:'gallery-1.svg',lqip:'gallery-1-lqip.svg',desc:'Global point-of-presence cache distribution ensuring millisecond latencies.'},{id:2,title:'Micro-Frontend Rendering',category:'Architecture',file:'gallery-2.svg',lqip:'gallery-2-lqip.svg',desc:'Isolating front-end packages and components for modular team delivery.'},{id:3,title:'Asset Minification Pipeline',category:'Build Systems',file:'gallery-3.svg',lqip:'gallery-3-lqip.svg',desc:'Compressing AST trees,stripping symbols and reducing bundle payloads.'},{id:4,title:'Service Worker Offline Cache',category:'PWA',file:'gallery-4.svg',lqip:'gallery-4-lqip.svg',desc:'Intercepting fetch queries to serve pre-cached shell assets instantaneously.'},{id:5,title:'Intersection Observer Trigger',category:'Browser APIs',file:'gallery-5.svg',lqip:'gallery-5-lqip.svg',desc:'Monitoring DOM visibility intersections to stream lazy-bound resources.'},{id:6,title:'Core Web Vitals Optimization',category:'Performance',file:'gallery-6.svg',lqip:'gallery-6-lqip.svg',desc:'Fine-tuning Largest Contentful Paint,Cumulative Layout Shift,and INP.'},{id:7,title:'Browser Cache Hierarchy',category:'HTTP Specs',file:'gallery-7.svg',lqip:'gallery-7-lqip.svg',desc:'Multi-tiered storage balancing memory cache,disk cache,and revalidation.'},{id:8,title:'HTTP/2&HTTP/3 Multiplexing',category:'Networking',file:'gallery-8.svg',lqip:'gallery-8-lqip.svg',desc:'Simultaneous binary frame transfers across a single persistent TCP/QUIC stream.'}];function initLazyLoading(){var lazyImages=[].slice.call(document.querySelectorAll('img.progressive-lazy'));if('IntersectionObserver' in window){var imageObserver=new IntersectionObserver(function(entries,observer){entries.forEach(function(entry){if(entry.isIntersecting){var image=entry.target;var fullSrc=image.getAttribute('data-src');if(fullSrc){image.src=fullSrc;image.onload=function(){image.classList.remove('lazy-loading');image.classList.add('lazy-loaded');var badge=image.parentElement.querySelector('.lazy-badge');if(badge)badge.innerText='Loaded';};}imageObserver.unobserve(image);}});},{rootMargin:'50px 0px'});lazyImages.forEach(function(image){imageObserver.observe(image);});}else{lazyImages.forEach(function(image){image.src=image.getAttribute('data-src');});}}function renderOptimizedGallery(targetId){var container=document.getElementById(targetId);if(!container)return;var html='';galleryItems.forEach(function(item){html+='<article class="card">';html+='<div class="card-image-wrap">';html+='<span class="lazy-badge">Pending</span>';html+='<img class="progressive-lazy lazy-loading" src="images/'+item.lqip+'" data-src="images/'+item.file+'" alt="'+item.title+'" width="800" height="520" loading="lazy" decoding="async"/>';html+='</div>';html+='<div class="card-body">';html+='<span class="card-tag">'+item.category+'</span>';html+='<h3 class="card-title">'+item.title+'</h3>';html+='<p class="card-text">'+item.desc+'</p>';html+='</div>';html+='</article>';});container.innerHTML=html;initLazyLoading();}function registerServiceWorker(){if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').then(function(reg){var swStatus=document.getElementById('sw-status');if(swStatus)swStatus.innerText='Active(Cache-First Enabled)';}).catch(function(err){});}}document.addEventListener('DOMContentLoaded',function(){renderOptimizedGallery('gallery-grid');registerServiceWorker();window.addEventListener('load',function(){var timing=window.performance.timing;var loadTime=timing.loadEventEnd-timing.navigationStart;var metricDisplay=document.getElementById('load-time-metric');if(metricDisplay)metricDisplay.innerText=loadTime+' ms';});});